  return () => {
    if (released) return;
    released = true;
    if (--state.users === 0) {
      if (state.original === null) root.removeAttribute("data-element-scrollbar");
      else root.setAttribute("data-element-scrollbar", state.original);
      elementScrollRoots.delete(root);
    }
  };
}

